  });\n\n\n            // Set the date we\'re counting down to\n            var countDownDate = new Date(\"2028-12-12T23:59:59\").getTime();\n            var removed = false;\n            var shown = false;\n\n            updateTime();\n\n            var x;\n            if (!removed) {\n              // Update the count down every 1 second\n              x = setInterval(function() {\n                updateTime();\n              }, 1000);\n            }\n\n            function updateTime() {\n              // Get today\'s date and time\n              var now = new Date().getTime();\n\n              // Find the distance between now and the count down date\n              var distance = countDownDate - now;\n\n              // Time calculations for days, hours, minutes and seconds\n              var days = Math.floor(distance / (1000 * 60 * 60 * 24));\n              var hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));\n              var minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));\n              var seconds = Math.floor((distance % (1000 * 60)) / 1000);\n\n              // Display the result in the element with id=\"superb_discount_bar_countdown\"\n              // document.getElementById(\"superb_discount_bar_countdown\").innerHTML = \"<div>\" + days + \"<span>Days</span>\" + \"</div><div>\" + hours + \"<span>Hours</span>\" + \"</div><div>\"  + minutes + \"<span>Minutes</span>\" +\"</div><div>\" + seconds + \"<span>Seconds</span>\" +\"</div>\";\n              var top_element = document.getElementById(\"superb_discount_bar_countdown\");\n              var pricing_element = document.getElementById(\"superb_discount_bar_countdown_pricing\");\n              if (top_element != null) {\n                top_element.innerHTML = \"<div>\" + hours + \"<span>Hours</span>\" + \"</div><div>\" + minutes + \"<span>Minutes</span>\" + \"</div><div>\" + seconds + \"<span>Seconds</span>\" + \"</div>\";\n              }\n              if (pricing_element != null) {\n                pricing_element.innerHTML = \"<div>\" + hours + \"<span>Hours</span>\" + \"</div><div>\" + minutes + \"<span>Minutes</span>\" + \"</div><div>\" + seconds + \"<span>Seconds</span>\" + \"</div>\";\n              }\n              var class_element = document.getElementsByClassName(\'superb_discount_bar_countdown_value\');\n              if (class_element != null && class_element.length >= 1) {\n                for (var i = 0; i < class_element.length; i++) {\n                  class_element[i].innerHTML = \"<div>\" + hours + \"<span>Hours</span>\" + \"</div><div>\" + minutes + \"<span>Minutes</span>\" + \"</div><div>\" + seconds + \"<span>Seconds</span>\" + \"</div>\";\n                }\n              }\n\n              // If the count down is finished, write some text\n              if (distance < 0) {\n                removed = true;\n                clearInterval(x);\n                if (top_element != null) {\n                  top_element.innerHTML = \"EXPIRED\";\n                }\n                if (pricing_element != null) {\n                  pricing_element.innerHTML = \"EXPIRED\";\n                }\n                if (class_element != null && class_element.length >= 1) {\n                  for (var i = 0; i < class_element.length; i++) {\n                    class_element[i].innerHTML = \"EXPIRED\";\n                  }\n                }\n                $(\"#superb_discount_bar\").remove();\n              } else if (!shown) {\n                shown = true;\n                $(\"#superb_discount_bar\").show();\n              }\n            }\n\n          });\n        });\n      </script>\n\n    	<div id=\"page\" class=\"site\">\n		<header id=\"masthead\" class=\"sheader site-header clearfix\">\n			<nav id=\"primary-site-navigation\" class=\"primary-menu main-navigation clearfix\">\n\n				<a href=\"#\" id=\"pull\" class=\"smenu-hide toggle-mobile-menu menu-toggle\" aria-controls=\"secondary-menu\" aria-expanded=\"